-- Check how many transaction records are linked to compliance cases (likely insider trades)
SELECT COUNT(*) FROM transactionrecord t 
JOIN compliancecase c ON t.transreg = c.transref;

-- Check how many transactions have sentiment data
SELECT COUNT(*) FROM transactionrecord t 
JOIN sentimentandfundamentals s ON t.transreg = s.transref;

-- Let me check the relationship between compliance cases and investigation details
SELECT COUNT(*) FROM compliancecase c 
JOIN investigationdetails i ON c.compreg = i.compref;

-- Let me check the enforcement actions more carefully to understand what constitutes "likely insider trades"
-- Perhaps it's those with Restriction or Suspension (strongest enforcement)

SELECT acttake, COUNT(*) FROM enforcementactions GROUP BY acttake;
